class Flaky:
    """A function that fails `failures` times in a row, then returns `result`."""

    def __init__(self, failures, error=ConnectionError, result="ok"):
        self.failures = failures
        self.error = error
        self.result = result
        self.calls = 0

    def __call__(self):
        self.calls += 1
        if self.calls <= self.failures:
            raise self.error(f"failure {self.calls}")
        return self.result


def run(failures, error=ConnectionError, result="ok", **options):
    """Runs retry() on a Flaky function with base=1 and cap=10 unless told otherwise. `sleep` records what it is given
    and `uniform(a, b)` answers the middle of its range, so the recorded waits are half of each backoff bound."""
    flaky = Flaky(failures, error, result)
    waits = []
    options.setdefault("base", 1)
    options.setdefault("cap", 10)
    try:
        outcome = {"returned": retry(flaky, sleep=waits.append, uniform=lambda a, b: (a + b) / 2, **options)}
    except BaseException as caught:
        outcome = {"raised": f"{type(caught).__name__}: {caught}"}
    outcome["calls"] = flaky.calls
    outcome["waits"] = waits
    return outcome

