import random
import time


def retry(fn, attempts=5, base=0.1, cap=5.0, retry_on=(Exception,), sleep=time.sleep, uniform=random.uniform):
    for attempt in range(attempts):
        try:
            return fn()
        except retry_on:
            if attempt == attempts - 1:
                raise                                          # out of attempts: the caller sees the last error
            sleep(uniform(0, min(cap, base * 2 ** attempt)))   # full jitter: anywhere from 0 to the backoff
